const state = {board:null, cls:null, subject:null, chapter:null};

const $ = id => document.getElementById(id);
function hideAll(){document.querySelectorAll(".screen").forEach(x=>x.classList.remove("active"))}
function show(id){hideAll();$(id).classList.add("active");window.scrollTo({top:0,behavior:"smooth"})}
function goHome(){show("home")}
function selectBoard(board){
  if(board==='ICSE/CISCE') board='ICSE / CISCE';
  state.board=board; $("boardCrumb").textContent=board; renderClasses(); show("boardScreen");
}
function showBoard(){ if(!state.board) return goHome(); renderClasses(); show("boardScreen"); }
function renderClasses(){
  const grid=$("classGrid"); grid.innerHTML="";
  for(let i=1;i<=12;i++){
    const card=document.createElement("button"); card.className="class-card";
    const subjects=DB[state.board]?.[String(i)] || {};
    const subjectCount=Object.keys(subjects).length;
    card.innerHTML=`<div class="class-number">${i}</div><h3>Class ${i}</h3><p>${subjectCount} subjects available</p>`;
    card.onclick=()=>selectClass(String(i)); grid.appendChild(card);
  }
}
function selectClass(cls){
  state.cls=cls; $("subjectCrumb").textContent=`${state.board} • Class ${cls}`; renderSubjects(); show("subjectScreen");
}
function showSubjects(){if(!state.cls)return showBoard();renderSubjects();show("subjectScreen")}
function iconFor(s){
  const m={Mathematics:"∑",Science:"⚗",Physics:"Φ",Chemistry:"⚗",Biology:"🧬",English:"A",Hindi:"ह",Sanskrit:"स",Computer:"⌘","Computer Science":"⌘","Social Science":"🌍","History":"⌛","History & Civics":"⚖",Geography:"🌎",Economics:"₹","Business Studies":"▣",Accountancy:"₿","Physical Education":"⚽","General Knowledge":"★"};
  return m[s]||"•";
}
function renderSubjects(){
  const grid=$("subjectGrid");grid.innerHTML="";
  const subjects=DB[state.board]?.[state.cls] || {};
  if(!Object.keys(subjects).length){grid.innerHTML=`<div class="empty-state"><h3>No subjects found</h3><p>This class has not been loaded correctly.</p></div>`;return}
  Object.keys(subjects).forEach(subject=>{
    const card=document.createElement("button");card.className="subject-card";
    const count=(DB[state.board]?.[state.cls]?.[subject]||[]).length;
    card.innerHTML=`<div class="subject-icon">${iconFor(subject)}</div><div><h3>${escapeHtml(subject)}</h3><p>${count} chapters/topics</p></div>`;
    card.onclick=()=>selectSubject(subject);grid.appendChild(card);
  });
}
function selectSubject(subject){
  state.subject=subject;$("chapterCrumb").textContent=subject;renderChapters();show("chapterScreen");
}
function showChapters(){if(!state.subject)return showSubjects();renderChapters();show("chapterScreen")}
function renderChapters(){
  const grid=$("chapterGrid");grid.innerHTML="";
  const chapters=DB[state.board]?.[state.cls]?.[state.subject]||[];
  chapters.forEach((ch,i)=>{
    const card=document.createElement("button");card.className="chapter-card";
    card.innerHTML=`<span class="chapter-no">${String(i+1).padStart(2,"0")}</span><div><h3>${escapeHtml(ch.title)}</h3><p>${escapeHtml(ch.notes)}</p></div>`;
    card.onclick=()=>openNotes(i);grid.appendChild(card);
  });
}
function openNotes(i){
  const chapters=DB[state.board]?.[state.cls]?.[state.subject]||[];state.chapter=chapters[i];
  if(!state.chapter){return showChapters()}
  $("notesCrumb").textContent=state.chapter.title;
  const a=$("notesArticle");
  a.innerHTML=`
    <span class="tag">${escapeHtml(state.board)} • CLASS ${state.cls}</span>
    <h1>${escapeHtml(state.chapter.title)}</h1>
    <div class="meta">${escapeHtml(state.subject)} • Chapter / Topic Notes</div>
    <div class="notes-section"><h2>Quick Notes</h2><p>${escapeHtml(state.chapter.notes)}</p></div>
    <div class="notes-section"><h2>How to study this topic</h2><p>Read the definition or central idea first. Then write 3–5 key points in your own words, solve textbook examples, and test yourself without looking at the page.</p></div>
    <div class="notes-section"><h2>Revision checklist</h2><p>✓ Can you explain the main idea? &nbsp; ✓ Can you define important terms? &nbsp; ✓ Can you solve a basic question? &nbsp; ✓ Can you give one real-life example?</p></div>
    <div class="tip"><b>StudyHub tip</b><span>Use this page for revision, but always follow your school's prescribed textbook, syllabus and teacher's instructions for board examinations.</span></div>`;
  show("notesScreen");
}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]))}
function runSearch(){
  const q=$("searchInput").value.trim().toLowerCase(), box=$("searchResults");box.innerHTML="";
  if(!q){box.innerHTML="<p>Type something to search.</p>";return}
  let found=[];
  Object.entries(DB).forEach(([board,classes])=>Object.entries(classes).forEach(([cls,subs])=>Object.entries(subs).forEach(([subject,chapters])=>chapters.forEach((ch,i)=>{
    if(`${board} ${cls} ${subject} ${ch.title} ${ch.notes}`.toLowerCase().includes(q)) found.push({board,cls,subject,ch,i});
  }))));
  if(!found.length){box.innerHTML="<p>No matching topic found. Try another keyword.</p>";return}
  found.slice(0,50).forEach(r=>{
    const div=document.createElement("button");div.className="result";
    div.innerHTML=`<b>${escapeHtml(r.board)} • Class ${r.cls} • ${escapeHtml(r.subject)}</b><h3>${escapeHtml(r.ch.title)}</h3><p>${escapeHtml(r.ch.notes)}</p>`;
    div.onclick=()=>{state.board=r.board;state.cls=r.cls;state.subject=r.subject;openNotes(r.i)};box.appendChild(div);
  });
}
$("searchBtn").onclick=()=>{show("searchScreen");$("searchInput").focus()}
$("searchInput").addEventListener("keydown",e=>{if(e.key==="Enter")runSearch()})
$("themeBtn").onclick=()=>{document.body.classList.toggle("dark");localStorage.setItem("studyhub-theme",document.body.classList.contains("dark")?"dark":"light")}
if(localStorage.getItem("studyhub-theme")==="dark")document.body.classList.add("dark");

// ---------- StudyHub AI ----------
function showAI(){
  show("aiScreen");
  const s = document.getElementById("aiSubject");
  if(state.subject) s.value = state.subject;
  const c = document.getElementById("aiClass");
  if(state.cls) c.value = state.cls;
  document.getElementById("aiBoard").value = state.board || "CBSE";
  document.getElementById("aiQuestion").focus();
}
function fillAI(text){document.getElementById("aiQuestion").value=text;document.getElementById("aiQuestion").focus()}
function addChat(role,text){
  const box=document.getElementById("chatBox");
  const d=document.createElement("div"); d.className="chat-msg "+role;
  d.innerHTML=`<b>${role==="user"?"You":"StudyHub AI"}</b><span>${escapeHtml(text)}</span>`;
  box.appendChild(d); box.scrollTop=box.scrollHeight;
}
async function askStudyHub(){
  const q=document.getElementById("aiQuestion").value.trim();
  if(!q) return;
  const btn=document.getElementById("askAiBtn");
  const board=document.getElementById("aiBoard").value;
  const cls=document.getElementById("aiClass").value;
  const subject=document.getElementById("aiSubject").value.trim() || "General";
  addChat("user",q); document.getElementById("aiQuestion").value="";
  btn.disabled=true; btn.textContent="Thinking…";
  addChat("assistant","I'm thinking...");
  const box=document.getElementById("chatBox");
  try{
    const response=await fetch("/api/ask",{
      method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({question:q,board,className:cls,subject})
    });
    const data=await response.json();
    box.lastElementChild.remove();
    if(!response.ok) throw new Error(data.error||"AI server error");
    addChat("assistant",data.answer);
  }catch(err){
    box.lastElementChild.remove();
    addChat("assistant","I couldn't connect to the AI server. Make sure the StudyHub server is running and its AI API key is configured.");
  }finally{btn.disabled=false;btn.textContent="Ask"}
}
document.getElementById("askBtn").onclick=showAI;
document.getElementById("aiQuestion").addEventListener("keydown",e=>{
  if((e.ctrlKey||e.metaKey)&&e.key==="Enter") askStudyHub();
});
